    private Icons() { }

    /**
     * A square icon of the given size. Unknown names give the "dot" icon. The shape keeps its proportions:
     * it is drawn at Material's 24-unit size and then scaled, so thin icons (minus, chevron) are not stretched.
     */
    static Region icon(String name, double size, String... styleClasses) {
        Region shape = new Region();
        shape.setStyle("-fx-shape: \"" + PATHS.getOrDefault(name, PATHS.get("dot")) + "\"; -fx-scale-shape: false;");
        shape.getStyleClass().add("nv-icon");
        shape.getStyleClass().addAll(styleClasses);
        shape.setMinSize(24, 24);
        shape.setPrefSize(24, 24);
        shape.setMaxSize(24, 24);
        shape.setScaleX(size / 24);
        shape.setScaleY(size / 24);
        StackPane box = new StackPane(new Group(shape));
        box.setMinSize(size, size);
        box.setPrefSize(size, size);
        box.setMaxSize(size, size);
        box.setMouseTransparent(true);
        return box;
    }

    static boolean has(String name) {
        return PATHS.containsKey(name);
    }
